import java.util.*;

class Solution {
    private int[][] trie = new int[100001][26];
    private boolean[] isEnd = new boolean[100001];
    private int cnt = 1;

    public String replaceWords(List<String> dictionary, String sentence) {
        for (String root : dictionary) {
            int node = 0;
            for (char c : root.toCharArray()) {
                int idx = c - 'a';
                if (trie[node][idx] == 0) trie[node][idx] = cnt++;
                node = trie[node][idx];
            }
            isEnd[node] = true;
        }

        StringBuilder sb = new StringBuilder();
        for (String word : sentence.split(" ")) {
            if (sb.length() > 0) sb.append(' ');
            sb.append(findRoot(word));
        }
        return sb.toString();
    }

    private String findRoot(String word) {
        int node = 0;
        for (int i = 0; i < word.length(); i++) {
            int idx = word.charAt(i) - 'a';
            if (trie[node][idx] == 0) break;
            node = trie[node][idx];
            if (isEnd[node]) return word.substring(0, i + 1);
        }
        return word;
    }
}

import java.util.*;

class Solution {
    public String replaceWords(List<String> dictionary, String sentence) {
        Set<String> rootSet = new HashSet<>(dictionary);
        String[] words = sentence.split(" ");
        StringBuilder sb = new StringBuilder();

        for (int w = 0; w < words.length; w++) {
            if (w > 0) sb.append(' ');
            String word = words[w];
            String replacement = word;
            for (int i = 1; i <= word.length(); i++) {
                String prefix = word.substring(0, i);
                if (rootSet.contains(prefix)) {
                    replacement = prefix;
                    break;
                }
            }
            sb.append(replacement);
        }
        return sb.toString();
    }
}
